     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * V 모드 내장 함수 처리
    21→   */
    22→  private readonly V_BUILTINS = new Set(['println', 'print', 'len', 'to_string', 'int_cast']);
    23→
    24→  /**
    25→   * 프로그램 전체 코드 생성
    26→   */
    27→  generate(program: AST.Program): CodegenResult {
    28→    // @mode 마커는 무시하고 함수/문장만 처리
    29→    for (const item of program.body) {
    30→      const fnItem = item as any;
    31→      if (fnItem.type === 'VFunction') {
    32→        this.genVFunction(fnItem as AST.VFunction);
    33→      } else if (fnItem.type === 'PyFunction') {
    34→        this.genPyFunction(fnItem as AST.PyFunction);
    35→      } else if (fnItem.type === 'StructDef') {
    36→        this.genVStructDef(fnItem as AST.StructDef);
    37→        this.genPyStructDef(fnItem as AST.StructDef);
    38→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    39→        // 탑레벨 문장은 V 모드(C)로 처리
    40→        this.genVStatement(fnItem as AST.Statement);
    41→      }
    42→    }
    43→
    44→    const c = this.cLines.join('\n');
    45→    const python = this.pyLines.join('\n');
    46→
    47→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    48→    const mixed =
    49→      c && python
    50→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    51→        : c || python;
    52→
    53→    return { c, python, mixed };
    54→  }
    55→
    56→  /**
    57→   * 실행 가능한 프로그램 생성
    58→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    59→   */
    60→  generateProgram(program: AST.Program): CodegenResult {
    61→    const base = this.generate(program);
    62→
    63→    // C 코드에 헤더 + main() wrapping 추가
    64→    const cWithMain = base.c
    65→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    66→      : '';
    67→
    68→    // Python 코드에 main 블록 추가
    69→    const pyWithMain = base.python
    70→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    71→      : '';
    72→
    73→    return {
    74→      c: cWithMain,
    75→      python: pyWithMain,
    76→      mixed: base.mixed,
    77→    };
    78→  }
    79→
    80→  /**
    81→   * V 함수 → C 함수
    82→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    83→   * →
    84→   * long long add(long long x, long long y) { return x + y; }
    85→   */
    86→  private genVFunction(fn: AST.VFunction): void {
    87→    // 반환타입
    88→    const returnType = this.mapVType(fn.returnType || 'void');
    89→
    90→    // 파라미터 리스트
    91→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    92→
    93→    // 함수 시그니처
    94→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    95→
    96→    // 함수 본문
    97→    this.indentLevel++;
    98→    for (const stmt of fn.body) {
    99→      this.genVStatement(stmt);
   100→    }
   101→    this.indentLevel--;
   102→
   103→    this.writeC('}');
   104→    this.writeC(''); // 빈 줄
   105→  }
   106→
   107→  /**
   108→   * Python 함수 → Python 함수
   109→   * def slow(items): return items
   110→   * →
   111→   * def slow(items):
   112→   *     return items
   113→   */
   114→  private genPyFunction(fn: AST.PyFunction): void {
   115→    // 파라미터 리스트
   116→    const paramList = fn.params.map((p) => p.name).join(', ');
   117→
   118→    // 함수 정의
   119→    this.writePy(`def ${fn.name}(${paramList}):`);
   120→
   121→    // 함수 본문 (들여쓰기 필요)
   122→    this.indentLevel++;
   123→    for (const stmt of fn.body) {
   124→      this.genPyStatement(stmt);
   125→    }
   126→    this.indentLevel--;
   127→
   128→    this.writePy(''); // 빈 줄
   129→  }
   130→
   131→  /**
   132→   * 구조체 정의 → C typedef
   133→   * struct Person { name: string, age: i64 }
   134→   * →
   135→   * typedef struct {
   136→   *   char* name;
   137→   *   long long age;
   138→   * } Person;
   139→   */
   140→  private genVStructDef(def: AST.StructDef): void {
   141→    this.writeC(`typedef struct {`);
   142→    for (const field of def.fields) {
   143→      const cType = this.mapVType(field.typeAnnotation);
   144→      this.writeC(`  ${cType} ${field.name};`);
   145→    }
   146→    this.writeC(`} ${def.name};`);
   147→    this.writeC(''); // 빈 줄
   148→  }
   149→
   150→  /**
   151→   * 구조체 정의 → Python class
   152→   * struct Person { name: string, age: i64 }
   153→   * →
   154→   * class Person:
   155→   *     def __init__(self, name, age):
   156→   *         self.name = name
   157→   *         self.age = age
   158→   */
   159→  private genPyStructDef(def: AST.StructDef): void {
   160→    this.writePy(`class ${def.name}:`);
   161→    const params = def.fields.map((f) => f.name).join(', ');
   162→    this.indentLevel++;
   163→    this.writePy(`def __init__(self, ${params}):`);
   164→    this.indentLevel++;
   165→    for (const field of def.fields) {
   166→      this.writePy(`self.${field.name} = ${field.name}`);
   167→    }
   168→    this.indentLevel -= 2;
   169→    this.writePy(''); // 빈 줄
   170→  }
   171→
   172→  /**
   173→   * V 문장 생성 (C 코드용)
   174→   */
   175→  private genVStatement(stmt: AST.Statement): void {
   176→    const s = stmt as any;
   177→
   178→    if (s.type === 'Return') {
   179→      const returnStmt = s as AST.ReturnStatement;
   180→      if (returnStmt.value) {
   181→        const expr = this.genVExpression(returnStmt.value);
   182→        this.writeC(`${this.indent()}return ${expr};`);
   183→      } else {
   184→        this.writeC(`${this.indent()}return;`);
   185→      }
   186→    } else if (s.type === 'Assign') {
   187→      const assignStmt = s as AST.AssignStatement;
   188→      const expr = this.genVExpression(assignStmt.value);
   189→      // 값의 타입에 따라 C 타입 결정
   190→      const value = assignStmt.value as any;
   191→      let cType = 'long long'; // 기본값
   192→      if (value.type === 'String') {
   193→        cType = 'char*'; // 문자열 리터럴
   194→      }
   195→      this.writeC(`${this.indent()}${cType} ${assignStmt.name} = ${expr};`);
   196→    } else if (s.type === 'ExprStatement') {
   197→      const exprStmt = s as AST.ExprStatement;
   198→      const expr = this.genVExpression(exprStmt.expression);
   199→      this.writeC(`${this.indent()}${expr};`);
   200→    } else if (s.type === 'IfStatement') {
   201→      const ifStmt = s as AST.IfStatement;
   202→      const cond = this.genVExpression(ifStmt.condition);
   203→      this.writeC(`${this.indent()}if (${cond}) {`);
   204→      this.indentLevel++;
   205→      for (const stmt of ifStmt.thenBranch) {
   206→        this.genVStatement(stmt);
   207→      }
   208→      this.indentLevel--;
   209→      this.writeC(`${this.indent()}}`);
   210→      if (ifStmt.elseBranch) {
   211→        this.writeC(`${this.indent()}else {`);
   212→        this.indentLevel++;
   213→        for (const stmt of ifStmt.elseBranch) {
   214→          this.genVStatement(stmt);
   215→        }
   216→        this.indentLevel--;
   217→        this.writeC(`${this.indent()}}`);
   218→      }
   219→    } else if (s.type === 'WhileStatement') {
   220→      const whileStmt = s as AST.WhileStatement;
   221→      const cond = this.genVExpression(whileStmt.condition);
   222→      this.writeC(`${this.indent()}while (${cond}) {`);
   223→      this.indentLevel++;
   224→      for (const stmt of whileStmt.body) {
   225→        this.genVStatement(stmt);
   226→      }
   227→      this.indentLevel--;
   228→      this.writeC(`${this.indent()}}`);
   229→    } else if (s.type === 'ForStatement') {
   230→      const forStmt = s as AST.ForStatement;
   231→      const iterExpr = forStmt.iterable as any;
   232→
   233→      // range(n) CallExpr 케이스
   234→      if (iterExpr.type === 'Call') {
   235→        const callee = iterExpr.callee as any;
   236→        const calleeName = callee.type === 'Identifier' ? callee.name : '';
   237→        if (calleeName === 'range' && iterExpr.args.length === 1) {
   238→          const limit = this.genVExpression(iterExpr.args[0]);
   239→          this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < ${limit}; ${forStmt.variable}++) {`);
   240→        } else {
   241→          // range가 아닌 일반 CallExpr - 기본 처리
   242→          const iterStr = this.genVExpression(forStmt.iterable);
   243→          this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < ${iterStr}; ${forStmt.variable}++) {`);
   244→        }
   245→      } else {
   246→        // 배열/변수 케이스: sizeof 패턴
   247→        const iterStr = this.genVExpression(forStmt.iterable);
   248→        this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < sizeof(${iterStr})/sizeof(${iterStr}[0]); ${forStmt.variable}++) {`);
   249→      }
   250→
   251→      this.indentLevel++;
   252→      for (const stmt of forStmt.body) {
   253→        this.genVStatement(stmt);
   254→      }
   255→      this.indentLevel--;
   256→      this.writeC(`${this.indent()}}`);
   257→    }
   258→  }
   259→
   260→  /**
   261→   * Python 문장 생성 (Python 코드용)
   262→   */
   263→  private genPyStatement(stmt: AST.Statement): void {
   264→    const s = stmt as any;
   265→    const indentStr = this.indent();
   266→
   267→    if (s.type === 'Return') {
   268→      const returnStmt = s as AST.ReturnStatement;
   269→      if (returnStmt.value) {
   270→        const expr = this.genPyExpression(returnStmt.value);
   271→        this.writePy(`${indentStr}return ${expr}`);
   272→      } else {
   273→        this.writePy(`${indentStr}return`);
   274→      }
   275→    } else if (s.type === 'Assign') {
   276→      const assignStmt = s as AST.AssignStatement;
   277→      const expr = this.genPyExpression(assignStmt.value);
   278→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   279→    } else if (s.type === 'ExprStatement') {
   280→      const exprStmt = s as AST.ExprStatement;
   281→      const expr = this.genPyExpression(exprStmt.expression);
   282→      this.writePy(`${indentStr}${expr}`);
   283→    } else if (s.type === 'WhileStatement') {
   284→      const whileStmt = s as AST.WhileStatement;
   285→      const cond = this.genPyExpression(whileStmt.condition);
   286→      this.writePy(`${indentStr}while ${cond}:`);
   287→      this.indentLevel++;
   288→      for (const stmt of whileStmt.body) {
   289→        this.genPyStatement(stmt);
   290→      }
   291→      this.indentLevel--;
   292→    } else if (s.type === 'ForStatement') {
   293→      const forStmt = s as AST.ForStatement;
   294→      const iter = this.genPyExpression(forStmt.iterable);
   295→      this.writePy(`${indentStr}for ${forStmt.variable} in ${iter}:`);
   296→      this.indentLevel++;
   297→      for (const stmt of forStmt.body) {
   298→        this.genPyStatement(stmt);
   299→      }
   300→      this.indentLevel--;
   301→    }
   302→  }
   303→
   304→  /**
   305→   * V 표현식 생성 (C 코드용)
   306→   */
   307→  private genVExpression(expr: AST.Expression): string {
   308→    const e = expr as any;
   309→
   310→    if (e.type === 'Number') {
   311→      return (e as AST.NumberLiteral).value.toString();
   312→    }
   313→
   314→    if (e.type === 'String') {
   315→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   316→      return (e as AST.StringLiteral).value;
   317→    }
   318→
   319→    if (e.type === 'Identifier') {
   320→      return (e as AST.Identifier).name;
   321→    }
   322→
   323→    if (e.type === 'BinaryExpr') {
   324→      const binExpr = e as AST.BinaryExpr;
   325→      const left = this.genVExpression(binExpr.left);
   326→      const right = this.genVExpression(binExpr.right);
   327→      return `${left} ${binExpr.operator} ${right}`;
   328→    }
   329→
   330→    if (e.type === 'Array') {
   331→      const arrayLit = e as AST.ArrayLiteral;
   332→      const elements = arrayLit.elements.map((el) => this.genVExpression(el)).join(', ');
   333→      return `{${elements}}`;
   334→    }
   335→
   336→    if (e.type === 'ArrayAccess') {
   337→      const arrayAccess = e as AST.ArrayAccess;
   338→      const obj = this.genVExpression(arrayAccess.object);
   339→      const idx = this.genVExpression(arrayAccess.index);
   340→      return `${obj}[${idx}]`;
   341→    }
   342→
   343→    if (e.type === 'Call') {
   344→      const callExpr = e as AST.CallExpr;
   345→
   346→      // callee가 Identifier인 경우 함수명 추출
   347→      let calleeStr: string | null = null;
   348→      if (typeof callExpr.callee === 'string') {
   349→        calleeStr = callExpr.callee;
   350→      } else {
   351→        const calleeExpr = callExpr.callee as any;
   352→        if (calleeExpr.type === 'Identifier') {
   353→          calleeStr = calleeExpr.name;
   354→        }
   355→      }
   356→
   357→      // V 내장 함수 처리
   358→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   359→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   360→      }
   361→
   362→      // 일반 함수 호출
   363→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   364→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   365→      return `${callee}(${args})`;
   366→    }
   367→
   368→    if (e.type === 'MemberAccess') {
   369→      const ma = e as AST.MemberAccess;
   370→      const obj = this.genVExpression(ma.object);
   371→      if (ma.property === 'length') {
   372→        // C에는 .length가 없으므로 sizeof 패턴 생성
   373→        return `(sizeof(${obj})/sizeof(${obj}[0]))`;
   374→      }
   375→      return `${obj}.${ma.property}`;
   376→    }
   377→
   378→    if (e.type === 'StructLiteral') {
   379→      const sl = e as AST.StructLiteral;
   380→      const entries = Object.entries(sl.fields);
   381→      const fieldsCode = entries.map(([k, v]) => `.${k} = ${this.genVExpression(v)}`).join(', ');
   382→      return `(${sl.name}){${fieldsCode}}`;
   383→    }
   384→
   385→    return '';
   386→  }
   387→
   388→  /**
   389→   * V 모드 내장 함수 호출 생성
   390→   */
   391→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   392→    if (name === 'println') {
   393→      if (args.length === 0) return 'printf("\\n")';
   394→      const firstArg = args[0] as any;
   395→      // StringLiteral인 경우: printf의 format string으로 사용
   396→      if (firstArg.type === 'String') {
   397→        // firstArg.value는 "text" 형태이므로 따옴표 제거
   398→        const str = firstArg.value.slice(1, -1);
   399→        return `printf("${str}\\n")`;
   400→      }
   401→      // 숫자/식별자인 경우 %lld 포맷 사용
   402→      const arg = this.genVExpression(firstArg);
   403→      return `printf("%lld\\n", ${arg})`;
   404→    }
   405→
   406→    if (name === 'print') {
   407→      if (args.length === 0) return 'printf("")';
   408→      const firstArg = args[0] as any;
   409→      if (firstArg.type === 'String') {
   410→        // StringLiteral인 경우: printf의 format string으로 사용
   411→        const str = firstArg.value.slice(1, -1);
   412→        return `printf("${str}")`;
   413→      }
   414→      const arg = this.genVExpression(firstArg);
   415→      return `printf("%lld", ${arg})`;
   416→    }
   417→
   418→    if (name === 'len') {
   419→      const firstArg = args[0] as any;
   420→      if (firstArg.type === 'String') {
   421→        // StringLiteral인 경우 따옴표 제거
   422→        const str = firstArg.value.slice(1, -1);
   423→        return `strlen("${str}")`;
   424→      }
   425→      const arg = this.genVExpression(firstArg);
   426→      return `strlen(${arg})`;
   427→    }
   428→
   429→    if (name === 'to_string') {
   430→      const arg = this.genVExpression(args[0]);
   431→      return arg; // 단순 pass-through
   432→    }
   433→
   434→    if (name === 'int_cast') {
   435→      const firstArg = args[0] as any;
   436→      if (firstArg.type === 'String') {
   437→        const str = firstArg.value.slice(1, -1);
   438→        return `atoi("${str}")`;
   439→      }
   440→      const arg = this.genVExpression(firstArg);
   441→      return `atoi(${arg})`;
   442→    }
   443→
   444→    return '';
   445→  }
   446→
   447→  /**
   448→   * Python 표현식 생성 (Python 코드용)
   449→   */
   450→  private genPyExpression(expr: AST.Expression): string {
   451→    const e = expr as any;
   452→
   453→    if (e.type === 'Number') {
   454→      return (e as AST.NumberLiteral).value.toString();
   455→    }
   456→
   457→    if (e.type === 'String') {
   458→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   459→      return (e as AST.StringLiteral).value;
   460→    }
   461→
   462→    if (e.type === 'Identifier') {
   463→      return (e as AST.Identifier).name;
   464→    }
   465→
   466→    if (e.type === 'BinaryExpr') {
   467→      const binExpr = e as AST.BinaryExpr;
   468→      const left = this.genPyExpression(binExpr.left);
   469→      const right = this.genPyExpression(binExpr.right);
   470→      return `${left} ${binExpr.operator} ${right}`;
   471→    }
   472→
   473→    if (e.type === 'Array') {
   474→      const arrayLit = e as AST.ArrayLiteral;
   475→      const elements = arrayLit.elements.map((el) => this.genPyExpression(el)).join(', ');
   476→      return `[${elements}]`;
   477→    }
   478→
   479→    if (e.type === 'ArrayAccess') {
   480→      const arrayAccess = e as AST.ArrayAccess;
   481→      const obj = this.genPyExpression(arrayAccess.object);
   482→      const idx = this.genPyExpression(arrayAccess.index);
   483→      return `${obj}[${idx}]`;
   484→    }
   485→
   486→    if (e.type === 'Call') {
   487→      const callExpr = e as AST.CallExpr;
   488→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   489→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   490→      return `${callee}(${args})`;
   491→    }
   492→
   493→    if (e.type === 'MemberAccess') {
   494→      const ma = e as AST.MemberAccess;
   495→      const obj = this.genPyExpression(ma.object);
   496→      if (ma.property === 'length') {
   497→        return `len(${obj})`;
   498→      }
   499→      return `${obj}.${ma.property}`;
   500→    }
   501→
   502→    if (e.type === 'StructLiteral') {
   503→      const sl = e as AST.StructLiteral;
   504→      const args = Object.entries(sl.fields)
   505→        .map(([k, v]) => `${k}=${this.genPyExpression(v)}`)
   506→        .join(', ');
   507→      return `${sl.name}(${args})`;
   508→    }
   509→
   510→    return '';
   511→  }
   512→
   513→  /**
   514→   * V 타입 → C 타입 매핑
   515→   */
   516→  private mapVType(type: string): string {
   517→    const mapping: Record<string, string> = {
   518→      i64: 'long long',
   519→      i32: 'int',
   520→      f64: 'double',
   521→      f32: 'float',
   522→      bool: 'bool',
   523→      string: 'char*',
   524→      void: 'void',
   525→    };
   526→
   527→    return mapping[type] || type;
   528→  }
   529→
   530→  /**
   531→   * Python 타입 → Python 타입 (기본값)
   532→   */
   533→  private mapPyType(type: string): string {
   534→    const mapping: Record<string, string> = {
   535→      i64: 'int',
   536→      i32: 'int',
   537→      f64: 'float',
   538→      f32: 'float',
   539→      bool: 'bool',
   540→      string: 'str',
   541→      void: 'None',
   542→      int: 'int',
   543→      float: 'float',
   544→    };
   545→
   546→    return mapping[type] || type;
   547→  }
   548→
   549→  /**
   550→   * C 코드에 줄 추가
   551→   */
   552→  private writeC(line: string): void {
   553→    this.cLines.push(line);
   554→  }
   555→
   556→  /**
   557→   * Python 코드에 줄 추가
   558→   */
   559→  private writePy(line: string): void {
   560→    this.pyLines.push(line);
   561→  }
   562→
   563→  /**
   564→   * 현재 들여쓰기 문자열
   565→   */
   566→  private indent(): string {
   567→    return '    '.repeat(this.indentLevel);
   568→  }
   569→}
