/**
 * FreeLang Nexus Phase N.4 테스트
 * - break / continue
 * - 배열 리터럴 선언 (타입 추론 + 명시적 타입)
 * - stdlib 확대: abs, min, max, sqrt, pow, str_len, str_contains, str_eq
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

function compile(code: string): string {
  const lexer = new NexusLexer(code);
  const tokens = lexer.tokenize();
  const parser = new NexusParser(tokens);
  const ast = parser.parse();
  const codegen = new NexusCodegen();
  return codegen.generate(ast).c;
}

// ─── break / continue ───────────────────────────────────────────────────────

describe('Phase N.4 - break / continue', () => {
  test('Test 1: while 루프 내 break', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let i = 0
  while i < 10 {
    if i == 5 {
      break
    }
    i = i + 1
  }
  return i
}`);
    expect(c).toContain('break;');
    expect(c).toContain('while (i < 10)');
  });

  test('Test 2: while 루프 내 continue', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let i = 0
  while i < 10 {
    i = i + 1
    if i == 3 {
      continue
    }
    println("hi")
  }
  return 0
}`);
    expect(c).toContain('continue;');
  });

  test('Test 3: for 루프 내 break', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  for i in range(100) {
    if i == 10 {
      break
    }
  }
  return 0
}`);
    expect(c).toContain('break;');
    expect(c).toContain('for (long long i = 0; i < 100; i++)');
  });

  test('Test 4: break AST 노드 타입', () => {
    const lexer = new NexusLexer(`@mode(v)
fn test() -> i64 {
  while 1 {
    break
  }
  return 0
}`);
    const ast = new NexusParser(lexer.tokenize()).parse();
    const fn = ast.body[0] as any;
    const whileStmt = fn.body[0] as any;
    const breakStmt = whileStmt.body[0] as any;
    expect(breakStmt.type).toBe('Break');
  });

  test('Test 5: continue AST 노드 타입', () => {
    const lexer = new NexusLexer(`@mode(v)
fn test() -> i64 {
  while 1 {
    continue
  }
  return 0
}`);
    const ast = new NexusParser(lexer.tokenize()).parse();
    const fn = ast.body[0] as any;
    const whileStmt = fn.body[0] as any;
    const continueStmt = whileStmt.body[0] as any;
    expect(continueStmt.type).toBe('Continue');
  });
});

// ─── 배열 선언 ───────────────────────────────────────────────────────────────

describe('Phase N.4 - 배열 선언', () => {
  test('Test 6: 배열 리터럴 타입 추론 (i64 원소)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let nums = [1, 2, 3]
  return 0
}`);
    expect(c).toContain('long long nums[3]');
    expect(c).toContain('{1, 2, 3}');
  });

  test('Test 7: 명시적 i64[] 타입 어노테이션', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let nums: i64[] = [10, 20, 30]
  return 0
}`);
    expect(c).toContain('long long nums[3]');
    expect(c).toContain('{10, 20, 30}');
  });

  test('Test 8: 배열 인덱싱', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let nums: i64[] = [1, 2, 3]
  return nums[0]
}`);
    expect(c).toContain('nums[0]');
  });

  test('Test 9: for-in + 배열 인덱싱 조합', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  for i in range(3) {
    println(i)
  }
  return 0
}`);
    expect(c).toContain('for (long long i = 0; i < 3; i++)');
    expect(c).toContain('printf("%lld\\n", i)');
  });

  test('Test 10: 빈 배열 파싱', () => {
    const lexer = new NexusLexer(`@mode(v)
fn test() -> i64 {
  let empty: i64[] = []
  return 0
}`);
    const ast = new NexusParser(lexer.tokenize()).parse();
    const fn = ast.body[0] as any;
    const assign = fn.body[0] as any;
    expect(assign.type).toBe('Assign');
    expect(assign.typeAnnotation).toBe('i64[]');
    expect(assign.value.type).toBe('Array');
    expect(assign.value.elements.length).toBe(0);
  });
});

// ─── stdlib 수학 ──────────────────────────────────────────────────────────────

describe('Phase N.4 - stdlib 수학 함수', () => {
  test('Test 11: abs(x) → llabs(x)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return abs(-42)
}`);
    expect(c).toContain('llabs(-42)');
  });

  test('Test 12: min(a, b) → 삼항 연산자', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return min(3, 7)
}`);
    expect(c).toContain('(3) < (7) ? (3) : (7)');
  });

  test('Test 13: max(a, b) → 삼항 연산자', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return max(10, 5)
}`);
    expect(c).toContain('(10) > (5) ? (10) : (5)');
  });

  test('Test 14: sqrt(x) → sqrt((double)(x))', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return sqrt(16)
}`);
    expect(c).toContain('sqrt((double)(16))');
  });

  test('Test 15: pow(base, exp) → pow(...)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return pow(2, 10)
}`);
    expect(c).toContain('pow((double)(2), (double)(10))');
  });

  test('Test 16: floor + ceil', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let a = floor(3)
  let b = ceil(3)
  return 0
}`);
    expect(c).toContain('floor((double)(3))');
    expect(c).toContain('ceil((double)(3))');
  });
});

// ─── stdlib 문자열 ────────────────────────────────────────────────────────────

describe('Phase N.4 - stdlib 문자열 함수', () => {
  test('Test 17: str_len(s) → strlen(s)', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return str_len("hello")
}`);
    expect(c).toContain('strlen("hello")');
  });

  test('Test 18: str_contains(s, sub) → strstr != NULL', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return str_contains("hello world", "world")
}`);
    expect(c).toContain('strstr(');
    expect(c).toContain('!= NULL');
  });

  test('Test 19: str_eq(a, b) → strcmp == 0', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  return str_eq("abc", "abc")
}`);
    expect(c).toContain('strcmp(');
    expect(c).toContain('== 0');
  });

  test('Test 20: float_cast + bool_cast 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let f = float_cast(42)
  let b = bool_cast(1)
  return 0
}`);
    expect(c).toContain('(double)(42)');
    expect(c).toContain('(bool)(1)');
  });
});

/**
 * FreeLang Nexus Phase N.4 테스트
 * - break / continue
 * - 배열 리터럴 선언 (타입 추론 + 명시적 타입)
 * - stdlib 확대: abs, min, max, sqrt, pow, str_len, str_contains, str_eq
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';

function compile(code: string): string {
  const lexer = new NexusLexer(code);
  const tokens = lexer.tokenize();
  const parser = new NexusParser(tokens);
  const ast = parser.parse();
  const codegen = new NexusCodegen();
  return codegen.generate(ast).c;
}

// ─── break / continue ───────────────────────────────────────────────────────

describe('Phase N.4 - break / continue', () => {
  test('Test 1: while 루프 내 break 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let i = 0
  while i < 10 {
    if i == 5 {
      break
    }
    i = i + 1
  }
  return i
}`);
    expect(c).toContain('break;');
    expect(c).toContain('while (i < 10)');
  });

  test('Test 2: while 루프 내 continue 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  let i = 0
  while i < 10 {
    i = i + 1
    if i == 3 {
      continue
    }
    println("hi")
  }
  return 0
}`);
    expect(c).toContain('continue;');
  });

  test('Test 3: for 루프 내 break 코드젠', () => {
    const c = compile(`@mode(v)
fn test() -> i64 {
  for i in range(100) {
    if i == 10 {
      break
    }
  }
  return 0
}`);
    expect(c).toContain('break;');
    expect(c).toContain('for (long long i = 0; i < 100; i++)');
  });

  test('Test 4: break AST 노드 타입', () => {
    const lexer = new NexusLexer(`@mode(v)
fn test() -> i64 {
  while 1 {
    break
  }
  return 0
}`);
    const ast = new NexusParser(lexer.tokenize()).parse();
    const fn = ast.body[0] as any;
    const whileStmt = fn.body[0] as any;
    const breakStmt = whileStmt.body[0] as any;
    expect(breakStmt.type).toBe('Break');
  });

  test('Test 5: continue AST 노드 타입', () => {
    const lexer = new NexusLexer(`@mode(v)
fn test() -> i64 {
  while 1 {
    continue
  }
  return 0
}`);
    const ast = new NexusParser(lexer.tokenize()).parse();
    const fn = ast.body[0] as any;
    const whileStmt = fn.body[0] as any;
    const continueStmt = whileStmt.body[0] as any;
    expect(continueStmt.type).toBe('Continue');
  });
});

