run(result: CodegenResult): RunResult {
  const errors: string[] = [];
  let cOutput = '';
  let pythonOutput = '';

  // Rust/Go/Julia externLibs 사전 빌드 → linkFlags에 추가
  const extraFlags: string[] = [];
  for (const lib of (result.externLibs || [])) {
    if (lib.lang === 'rust') {
      const workDir = this.tmpFile('_rust_' + lib.alias);
      const soPath = NexusRunner.buildRustLib(lib.package, lib.alias, workDir);
      if (soPath) {
        extraFlags.push(`-L${path.dirname(soPath)}`, `-l${lib.alias}`);
      } else {
        errors.push(`Rust 빌드 실패: ${lib.package} (cargo build --release)`);
      }
    } else if (lib.lang === 'go') {
      const workDir = this.tmpFile('_go_' + lib.alias);
      const soPath = NexusRunner.buildGoLib(lib.package, lib.alias, workDir);
      if (soPath) {
        extraFlags.push(`-L${path.dirname(soPath)}`, `-l${lib.alias}`);
      } else {
        errors.push(`Go 빌드 실패: ${lib.package} (go build -buildmode=c-shared)`);
      }
    } else if (lib.lang === 'julia') {
      const juliaFlags = NexusRunner.getJuliaCFlags();
      extraFlags.push(...juliaFlags, '$(julia-config --ldflags --ldlibs)');
    }
  }

  // C 코드 실행 (linkFlags + extraFlags 자동 전달)
  if (result.c && result.c.trim()) {
    try {
      cOutput = this.runC(result.c, [...(result.linkFlags || []), ...extraFlags]);
    } catch (e) {
      errors.push(`C 컴파일/실행 에러: ${(e as Error).message}`);
    }
  }

