/**
 * FreeLang Nexus - End-to-End FFI 실제 실행 테스트
 *
 * FreeLang 소스 → Codegen → C 컴파일 → 실행까지 전체 파이프라인 검증
 * 각 언어 환경이 없으면 자동 skip
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import { NexusRunner } from '../src/nexus/runtime/nexus-runner';
import { execSync } from 'child_process';

// ─── 환경 감지 헬퍼 ─────────────────────────────────────────────────────────

function hasCmd(cmd: string): boolean {
  try { execSync(`which ${cmd}`, { stdio: 'pipe' }); return true; }
  catch { return false; }
}
function hasPython(): boolean {
  try { execSync('python3 -c "import sys"', { stdio: 'pipe' }); return true; }
  catch { return false; }
}
function hasNumpy(): boolean {
  try { execSync('python3 -c "import numpy"', { stdio: 'pipe' }); return true; }
  catch { return false; }
}
function hasJulia(): boolean { return hasCmd('julia') && hasCmd('julia-config'); }
function hasRust(): boolean { return hasCmd('cargo'); }
function hasGo(): boolean { return hasCmd('go'); }

// ─── 파이프라인 실행 헬퍼 ────────────────────────────────────────────────────

function runFreeLang(src: string): { output: string; errors: string[] } {
  const tokens = new NexusLexer(src).tokenize();
  const ast    = new NexusParser(tokens).parse();
  const result = new NexusCodegen().generateProgram(ast);
  const runner = new NexusRunner();
  const run    = runner.run(result);
  return { output: run.cOutput, errors: run.errors };
}

// ─── @call python:numpy - end-to-end ────────────────────────────────────────

describe('@call python:numpy - end-to-end 실행', () => {
  const skip = !hasNumpy();

  (skip ? test.skip : test)('E2E-1: np.add(2,3) → 5 출력', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call python:numpy as np
fn main() -> i64 {
  let x = np.add(2, 3)
  println(x)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('5');
  });

  (skip ? test.skip : test)('E2E-2: np.subtract(10,3) → 7 출력', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call python:numpy as np
fn main() -> i64 {
  let x = np.subtract(10, 3)
  println(x)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('7');
  });

  (skip ? test.skip : test)('E2E-3: @call python + while 루프 혼합', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call python:numpy as np
fn main() -> i64 {
  let i = 1
  while i <= 3 {
    let x = np.add(i, 10)
    println(x)
    i = i + 1
  }
  return 0
}
`);
    expect(errors).toHaveLength(0);
    const lines = output.trim().split('\n');
    expect(lines).toEqual(['11', '12', '13']);
  });
});

// ─── @call python:math - end-to-end ─────────────────────────────────────────

describe('@call python:math - end-to-end 실행', () => {
  const skip = !hasPython();

  (skip ? test.skip : test)('E2E-4: math.floor(7.9) → 7', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call python:math as m
fn main() -> i64 {
  let x = m.floor(7)
  println(x)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('7');
  });
});

// ─── @call c:m + FreeLang - end-to-end ──────────────────────────────────────

describe('@call c:m - end-to-end 실행 (math.h)', () => {
  test('E2E-5: sqrt(25) → 5', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call c:m
fn main() -> i64 {
  let x = sqrt(25)
  println(x)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('5');
  });

  test('E2E-6: pow(2,8) → 256', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call c:m
fn main() -> i64 {
  let x = pow(2, 8)
  println(x)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('256');
  });

  test('E2E-7: @call c:m + while + sqrt', () => {
    const { output, errors } = runFreeLang(`@mode(v)
@call c:m
fn main() -> i64 {
  let i = 1
  while i <= 4 {
    let s = sqrt(i * i)
    println(s)
    i = i + 1
  }
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('1\n2\n3\n4');
  });
});

// ─── @call c:sqlite3 - end-to-end ───────────────────────────────────────────

describe('@call c:sqlite3 - end-to-end 실행', () => {
  test('E2E-8: sqlite3 컴파일 + 실행 (빈 main)', () => {
    const { errors } = runFreeLang(`@mode(v)
@call c:sqlite3
fn main() -> i64 {
  return 0
