/**
 * FreeLang Nexus - 통합 Parser
 * V 모드 + Python 모드 함수를 혼합하여 파싱
 */

import { Token, TokenType } from '../lexer/token';
import * as AST from './ast';

export class NexusParser {
  private tokens: Token[];
  private pos: number = 0;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
  }

  /**
   * 파싱 진입점
   */
  parse(): AST.Program {
    const body: Array<AST.VFunction | AST.PyFunction | AST.StructDef | AST.Statement | AST.ExternCall> = [];

    while (!this.isAtEnd()) {
      this.skipNewlines();
      if (this.isAtEnd()) break;

      const token = this.peek();

      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
      if (token.type === TokenType.MODE_MARKER) {
        this.advance();
        continue;
      }

      // @call 디렉티브
      if (token.type === TokenType.CALL_DIRECTIVE) {
        const callNode = this.parseCallDirective();
        if (callNode) body.push(callNode);
        continue;
      }

      // 탑레벨 아이템 파싱
      const item = this.parseTopLevel();
      if (item) {
        body.push(item);
      }
    }

    return { type: 'Program', body };
  }

  /**
   * @call 디렉티브 파싱
   * 토큰 value: "@call python:numpy 1.24" 또는 "@call rust:rand as r"
   *
   * 문법: @call <lang>:<package> [<version>] [as <alias>]
   */
  private parseCallDirective(): AST.ExternCall | null {
    const token = this.advance(); // CALL_DIRECTIVE 토큰 소비
    const raw = token.value; // "@call python:numpy 1.24"

    // "@call " 제거
    const body = raw.slice('@call '.length).trim();

    // lang:package 분리
    const colonIdx = body.indexOf(':');
    if (colonIdx === -1) return null;

    const lang = body.slice(0, colonIdx).trim() as AST.ExternCall['lang'];
    const rest = body.slice(colonIdx + 1).trim();

    // "as alias" 분리
    let alias: string | undefined;
    let packageAndVersion = rest;
    const asIdx = rest.search(/\s+as\s+/);
    if (asIdx !== -1) {
      alias = rest.slice(asIdx).replace(/\s+as\s+/, '').trim();
      packageAndVersion = rest.slice(0, asIdx).trim();
    }

    // package와 version 분리 (마지막 공백 기준)
    const parts = packageAndVersion.split(/\s+/);
    const pkg = parts[0];
    const version = parts.length > 1 ? parts[parts.length - 1] : undefined;

    const supportedLangs = new Set(['python', 'rust', 'go', 'julia', 'js', 'c', 'cpp']);
    if (!supportedLangs.has(lang)) return null;

    return {
      type: 'ExternCall',
      lang,
      package: pkg,
      version,
      alias,
      line: token.line,
      column: token.column,
      mode: token.mode,
    };
  }

  /**
   * 탑레벨 아이템 파싱
   * V 함수, Python 함수, 구조체, 또는 문장
   */
  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.StructDef | AST.Statement | null {
    const token = this.peek();

    // V 모드 함수
    if (token.type === TokenType.FN) {
      return this.parseVFunction();
    }

    // Python 모드 함수
    if (token.type === TokenType.DEF) {
      return this.parsePyFunction();
    }

    // 구조체 정의
    if (token.type === TokenType.STRUCT) {
      return this.parseStructDef();
    }

    // 그 외: 문장
    return this.parseStatement();
  }

  /**
   * V 함수 파싱
   * fn name(params) -> type { body }
   */
  private parseVFunction(): AST.VFunction {
    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    const name = nameToken.value;

    this.consume(TokenType.LPAREN, '( 필요');
    const params = this.parseVParams();
    this.consume(TokenType.RPAREN, ') 필요');

    const returnType = this.parseReturnType();

    this.consume(TokenType.LBRACE, '{ 필요');
    const body = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'VFunction',
      name,
      params,
      returnType,
      body,
      mode: 'v',
      line: startToken.line,
      column: startToken.column,
    };
  }

  /**
   * Python 함수 파싱
   * def name(params): INDENT body DEDENT
   */
  private parsePyFunction(): AST.PyFunction {
    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    const name = nameToken.value;

    this.consume(TokenType.LPAREN, '( 필요');
    const params = this.parsePyParams();
    this.consume(TokenType.RPAREN, ') 필요');

    const returnType = this.parseReturnType();

    this.consume(TokenType.COLON, ': 필요');
    this.skipNewlines();

    const body = this.parsePyBlock();

    return {
      type: 'PyFunction',
      name,
      params,
      returnType,
      body,
      mode: 'python',
      line: startToken.line,
      column: startToken.column,
    };
  }

  /**
   * 구조체 정의 파싱
   * struct Person { name: string, age: i64 }
   */
  private parseStructDef(): AST.StructDef {
    const startToken = this.consume(TokenType.STRUCT, 'struct 키워드 필요');
    const nameToken = this.consume(TokenType.IDENTIFIER, '구조체 이름 필요');
    this.consume(TokenType.LBRACE, '{ 필요');
    this.skipNewlines();

    const fields: AST.StructField[] = [];
    while (this.peek().type !== TokenType.RBRACE && this.peek().type !== TokenType.EOF) {
      this.skipNewlines();
      if (this.peek().type === TokenType.RBRACE) break;

      const fieldNameToken = this.consume(TokenType.IDENTIFIER, '필드명 필요');
      this.consume(TokenType.COLON, ': 필요');
      const typeAnnotation = this.parseType();

      fields.push({
        name: fieldNameToken.value,
        typeAnnotation,
        line: fieldNameToken.line,
        column: fieldNameToken.column,
      });

      // 필드 구분자 , 선택적 소비
      if (this.peek().type === TokenType.COMMA) {
        this.advance();
      }
      this.skipNewlines();
    }

    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'StructDef',
      name: nameToken.value,
      fields,
      line: startToken.line,
      column: startToken.column,
      mode: 'v',
    };
  }

  /**
   * V 함수 파라미터 파싱
   * (x: i64, y: i64)
   */
  private parseVParams(): AST.Parameter[] {
    const params: AST.Parameter[] = [];

    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
      this.consume(TokenType.COLON, ': 필요');
      const typeToken = this.peek();
      const typeAnnotation = this.parseType();

      params.push({
        name: nameToken.value,
        typeAnnotation,
        line: nameToken.line,
        column: nameToken.column,
      });

      if (!this.check(TokenType.RPAREN)) {
        this.consume(TokenType.COMMA, ', 필요');
      }
    }

    return params;
  }

  /**
   * Python 함수 파라미터 파싱
   * (x, y) 또는 (x: int, y: int)
   */
  private parsePyParams(): AST.Parameter[] {
    const params: AST.Parameter[] = [];

    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
      let typeAnnotation: string | undefined;

      // 타입 어노테이션 (선택)
      if (this.check(TokenType.COLON)) {
        this.advance();
        typeAnnotation = this.parseType();
      }

      params.push({
        name: nameToken.value,
        typeAnnotation,
        line: nameToken.line,
        column: nameToken.column,
      });

      if (!this.check(TokenType.RPAREN)) {
        this.consume(TokenType.COMMA, ', 필요');
      }
    }

    return params;
  }

  /**
   * 반환 타입 파싱
   * -> i64 (선택)
   */
  private parseReturnType(): string | undefined {
    if (this.match(TokenType.ARROW)) {
      return this.parseType();
    }
    return undefined;
  }

  /**
   * 타입 파싱
   * i64, string, bool 등
   */
  private parseType(): string {
    const token = this.peek();

    // 기본 타입
    if (
      token.type === TokenType.I64 ||
      token.type === TokenType.I32 ||
      token.type === TokenType.F64 ||
      token.type === TokenType.F32 ||
      token.type === TokenType.U32 ||
      token.type === TokenType.U64 ||
      token.type === TokenType.BOOL ||
      token.type === TokenType.STRING_TYPE ||
      token.type === TokenType.CHAR ||
      token.type === TokenType.VOID ||
      token.type === TokenType.STRING ||
      token.type === TokenType.IDENTIFIER
    ) {
      return this.advance().value;
    }

    throw new Error(`타입 필요 at line ${token.line}`);
  }

  /**
   * 변수 선언 타입 어노테이션 파싱
   * i64, string, bool, i64[], f64[], string[] 등 (배열 타입 포함)
   */
  private parseTypeAnnotation(): string {
    const base = this.parseType();
    // 배열 타입: i64[], string[] 등
    if (this.check(TokenType.LBRACKET) && this.peekAt(1).type === TokenType.RBRACKET) {
      this.advance(); // [
      this.advance(); // ]
      return `${base}[]`;
    }
    return base;
  }

  /**
   * V 블록 파싱
   * { statements }
   */
  private parseVBlock(): AST.Statement[] {
    const statements: AST.Statement[] = [];

    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
      this.skipNewlines();

      if (this.check(TokenType.RBRACE)) break;

      const stmt = this.parseStatement();
      if (stmt) {
        statements.push(stmt);
      }

      this.skipNewlines();
    }

    return statements;
  }

  /**
   * Python 블록 파싱
   * INDENT statements DEDENT
   */
  private parsePyBlock(): AST.Statement[] {
    const statements: AST.Statement[] = [];

    this.consume(TokenType.INDENT, 'INDENT 필요');

    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
      this.skipNewlines();

      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;

      const stmt = this.parseStatement();
      if (stmt) {
        statements.push(stmt);
      }

      this.skipNewlines();
    }

    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
    if (this.check(TokenType.DEDENT)) {
      this.advance();
    }

    return statements;
  }

  /**
   * 문장 파싱
   */
  private parseStatement(): AST.Statement {
    const token = this.peek();

    // return 문장
    if (token.type === TokenType.RETURN) {
      return this.parseReturnStatement();
    }

    // if 문장
    if (token.type === TokenType.IF) {
      return this.parseIfStatement();
    }

    // while 루프
    if (token.type === TokenType.WHILE) {
      return this.parseWhileStatement();
    }

    // for 루프
    if (token.type === TokenType.FOR) {
      return this.parseForStatement();
    }

    // break 문장
    if (token.type === TokenType.BREAK) {
      const t = this.advance();
      return { type: 'Break', line: t.line, column: t.column, mode: t.mode };
    }

    // continue 문장
    if (token.type === TokenType.CONTINUE) {
      const t = this.advance();
      return { type: 'Continue', line: t.line, column: t.column, mode: t.mode };
    }

    // match 문장
    if (token.type === TokenType.MATCH) {
      return this.parseMatchStatement();
    }

    // pass 문장 (Python)
    if (token.type === TokenType.PASS) {
      const passToken = this.advance();
      return {
        type: 'ExprStatement',
        expression: {
          type: 'Identifier',
          name: 'pass',
          line: passToken.line,
          column: passToken.column,
          mode: passToken.mode,
        },
        line: passToken.line,
        column: passToken.column,
        mode: passToken.mode,
      };
    }

    // let 또는 식별자 (할당 가능성)
    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
      return this.parseAssignOrExpr();
    }

    // 기본값: 표현식 문장
    const expr = this.parseExpression();
    const startToken = this.peek();
    return {
      type: 'ExprStatement',
      expression: expr,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * match 문장 파싱
   * match x { case 1 => { ... } case _ => { ... } }
   */
  private parseMatchStatement(): AST.MatchStatement {
    const startToken = this.consume(TokenType.MATCH, 'match 키워드 필요');
    const subject = this.parseExpression();
    this.skipNewlines();
    this.consume(TokenType.LBRACE, '{ 필요');
    this.skipNewlines();

    const arms: AST.MatchArm[] = [];

    while (this.peek().type !== TokenType.RBRACE && !this.isAtEnd()) {
      this.skipNewlines();
      if (this.peek().type === TokenType.RBRACE) break;

      // case 키워드
      this.consume(TokenType.CASE, 'case 키워드 필요');

      // 패턴: _ (wildcard) 또는 표현식
      let pattern: AST.Expression | null;
      const patternToken = this.peek();
      if (patternToken.type === TokenType.IDENTIFIER && patternToken.value === '_') {
        this.advance(); // _ 소비
        pattern = null; // wildcard
      } else {
        pattern = this.parseExpression();
      }

      // => 화살표
      const arrowToken = this.peek();
      if (arrowToken.type === TokenType.IDENTIFIER && arrowToken.value === '=>') {
        this.advance();
      } else {
        throw new Error(`=> 필요, got: ${arrowToken.value} at line ${arrowToken.line}`);
      }

      // arm body: { ... } 블록 또는 단일 문장
      const body: AST.Statement[] = [];
      this.skipNewlines();
      if (this.peek().type === TokenType.LBRACE) {
        this.advance(); // { 소비
        this.skipNewlines();
        while (this.peek().type !== TokenType.RBRACE && !this.isAtEnd()) {
          this.skipNewlines();
          if (this.peek().type === TokenType.RBRACE) break;
          body.push(this.parseStatement());
          this.skipNewlines();
        }
        this.consume(TokenType.RBRACE, '} 필요');
      } else {
        body.push(this.parseStatement());
      }

      arms.push({
        pattern,
        body,
        line: patternToken.line,
        column: patternToken.column,
      });

      this.skipNewlines();
    }

    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'MatchStatement',
      subject,
      arms,
      mode: startToken.mode,
      line: startToken.line,
      column: startToken.column,
    };
  }

  /**
   * Return 문장 파싱
   */
  private parseReturnStatement(): AST.ReturnStatement {
    const startToken = this.consume(TokenType.RETURN, 'return 필요');
    let value: AST.Expression | undefined;

    // 반환값이 있으면 파싱
    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
      value = this.parseExpression();
    }

    return {
      type: 'Return',
      value,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * 할당 또는 표현식 파싱
   */
  private parseAssignOrExpr(): AST.Statement {
    const startToken = this.peek();

    // let x = value  또는  let x: type = value
    if (startToken.type === TokenType.LET) {
      this.advance();
      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');

      // 선택적 타입 어노테이션: : i64, : string, : i64[], : f64[] 등
      let typeAnnotation: string | undefined;
      if (this.check(TokenType.COLON)) {
        this.advance();
        typeAnnotation = this.parseTypeAnnotation();
      }

      this.consume(TokenType.EQUAL, '= 필요');
      const value = this.parseExpression();

      return {
        type: 'Assign',
        name: nameToken.value,
        typeAnnotation,
        value,
        line: startToken.line,
        column: startToken.column,
        mode: startToken.mode,
      };
    }

    // x = value 또는 함수호출 등
    if (startToken.type === TokenType.IDENTIFIER) {
      const nameToken = this.peek();
      const name = nameToken.value;
      this.advance();

      if (this.check(TokenType.EQUAL)) {
        this.advance();
        const value = this.parseExpression();

        return {
          type: 'Assign',
          name,
          value,
          line: startToken.line,
          column: startToken.column,
          mode: startToken.mode,
        };
      }

      // 아니면 전체 표현식으로 다시 파싱 (함수호출 등 포함)
      // pos를 한 칸 뒤로 이동하여 식별자부터 다시 파싱
      this.pos--;
      const expr = this.parseExpression();

      return {
        type: 'ExprStatement',
        expression: expr,
        line: startToken.line,
        column: startToken.column,
        mode: startToken.mode,
      };
    }

    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
  }

  /**
   * If 문장 파싱
   * if condition { body } [else { body }]
   */
  private parseIfStatement(): AST.IfStatement {
    const startToken = this.consume(TokenType.IF, 'if 키워드 필요');
    const condition = this.parseExpression();
    this.consume(TokenType.LBRACE, '{ 필요');
    const thenBranch = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    let elseBranch: AST.Statement[] | undefined;
    if (this.match(TokenType.ELSE)) {
      this.consume(TokenType.LBRACE, '{ 필요');
      elseBranch = this.parseVBlock();
      this.consume(TokenType.RBRACE, '} 필요');
    }

    return {
      type: 'IfStatement',
      condition,
      thenBranch,
      elseBranch,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * While 루프 파싱
   * while condition { body }
   */
  private parseWhileStatement(): AST.WhileStatement {
    const startToken = this.consume(TokenType.WHILE, 'while 키워드 필요');
    const condition = this.parseExpression();
    this.consume(TokenType.LBRACE, '{ 필요');
    const body = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'WhileStatement',
      condition,
      body,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * For-In 이터러블 파싱 (구조체 리터럴 제외: { 앞에서 멈춤)
   * for x in arr { ... } 에서 arr만 파싱
   * for x in range(n) { ... } 에서 range(n)만 파싱
   */
  private parseForIterable(): AST.Expression {
    let expr = this.parsePrimary();

    // 함수 호출만 허용 (구조체 리터럴 { 는 루프 본문이므로 제외)
    while (this.peek().type === TokenType.LPAREN || this.peek().type === TokenType.LBRACKET || this.peek().type === TokenType.DOT) {
      if (this.match(TokenType.LPAREN)) {
        const args = this.parseArguments();
        this.consume(TokenType.RPAREN, ') 필요');
        const token = this.previous();
        expr = {
          type: 'Call',
          callee: expr,
          args,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      } else if (this.match(TokenType.LBRACKET)) {
        const index = this.parseExpression();
        const token = this.consume(TokenType.RBRACKET, '] 필요');
        expr = {
          type: 'ArrayAccess',
          object: expr,
          index,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      } else if (this.match(TokenType.DOT)) {
        const propToken = this.consume(TokenType.IDENTIFIER, '프로퍼티명 필요');
        const token = this.previous();
        expr = {
          type: 'MemberAccess',
          object: expr,
          property: propToken.value,
          line: token.line,
          column: token.column,
          mode: token.mode,
        } as any;
      } else {
        break;
      }
    }

    return expr;
  }

  /**
   * For-In 루프 파싱
   * for <variable> in <iterable> { <body> }
   */
  private parseForStatement(): AST.ForStatement {
    const startToken = this.consume(TokenType.FOR, 'for 키워드 필요');
    const varToken = this.consume(TokenType.IDENTIFIER, '루프 변수명 필요');
    this.consume(TokenType.IN, 'in 키워드 필요');
    const iterable = this.parseForIterable();
    this.consume(TokenType.LBRACE, '{ 필요');
    const body = this.parseVBlock();
    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'ForStatement',
      variable: varToken.value,
      iterable,
      body,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * 표현식 파싱
   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   */
  private parseExpression(): AST.Expression {
    return this.parseLogicalOr();
  }

  /**
   * 논리 OR 파싱: ||
   */
  private parseLogicalOr(): AST.Expression {
    let expr = this.parseLogicalAnd();

    while (this.match(TokenType.OR)) {
      const operator = this.previous().value;
      const right = this.parseLogicalAnd();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 논리 AND 파싱: &&
   */
  private parseLogicalAnd(): AST.Expression {
    let expr = this.parseEquality();

    while (this.match(TokenType.AND)) {
      const operator = this.previous().value;
      const right = this.parseEquality();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 등호/부등호 파싱: ==, !=
   */
  private parseEquality(): AST.Expression {
    let expr = this.parseComparison();

    while (this.match(TokenType.EQ, TokenType.NE)) {
      const operator = this.previous().value;
      const right = this.parseComparison();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 비교 파싱: <, >, <=, >=
   */
  private parseComparison(): AST.Expression {
    let expr = this.parseAddition();

    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
      const operator = this.previous().value;
      const right = this.parseAddition();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 덧셈/뺄셈 파싱
   */
  private parseAddition(): AST.Expression {
    let expr = this.parseMultiplication();

    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
      const operator = this.previous().value;
      const right = this.parseMultiplication();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 곱셈/나눗셈 파싱
   */
  private parseMultiplication(): AST.Expression {
    let expr = this.parseUnary();

    while (this.match(TokenType.STAR, TokenType.SLASH)) {
      const operator = this.previous().value;
      const right = this.parseUnary();
      const token = this.previous();
      expr = {
        type: 'BinaryExpr',
        left: expr,
        operator,
        right,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    return expr;
  }

  /**
   * 단항 연산 파싱 (-, !)
   */
  private parseUnary(): AST.Expression {
    // 단항 음수: -expr
    if (this.check(TokenType.MINUS)) {
      const opToken = this.advance();
      const operand = this.parseUnary();
      // 숫자 리터럴이면 바로 음수로 접힘
      if (operand.type === 'Number') {
        const n = operand as AST.NumberLiteral;
        return {
          type: 'Number',
          value: `-${n.value}`,
          line: opToken.line,
          column: opToken.column,
          mode: opToken.mode,
        };
      }
      // 그 외: 0 - expr 로 변환
      return {
        type: 'BinaryExpr',
        left: { type: 'Number', value: 0, line: opToken.line, column: opToken.column, mode: opToken.mode },
        operator: '-',
        right: operand,
        line: opToken.line,
        column: opToken.column,
        mode: opToken.mode,
      };
    }

    // 논리 부정: !expr
    if (this.check(TokenType.NOT)) {
      const opToken = this.advance();
      const operand = this.parseUnary();
      return {
        type: 'BinaryExpr',
        left: { type: 'Number', value: 0, line: opToken.line, column: opToken.column, mode: opToken.mode },
        operator: '==',
        right: operand,
        line: opToken.line,
        column: opToken.column,
        mode: opToken.mode,
      };
    }

    return this.parsePostfix();
  }

  /**
   * 후위 연산 파싱 (함수 호출, 배열 접근, 구조체 리터럴)
   */
  private parsePostfix(): AST.Expression {
    let expr = this.parsePrimary();

    while (true) {
      // Identifier 뒤에 { 가 오면 구조체 리터럴
      if (expr.type === 'Identifier' && this.peek().type === TokenType.LBRACE) {
        const structName = (expr as AST.Identifier).name;
        expr = this.parseStructLiteral(structName, expr.line, expr.column);
        continue;
      }

      // 함수 호출: foo()
      if (this.match(TokenType.LPAREN)) {
        const args = this.parseArguments();
        this.consume(TokenType.RPAREN, ') 필요');

        const token = this.previous();
        expr = {
          type: 'Call',
          callee: expr,
          args,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      }
      // 배열 인덱싱: arr[0]
      else if (this.match(TokenType.LBRACKET)) {
        const index = this.parseExpression();
        const token = this.consume(TokenType.RBRACKET, '] 필요');

        expr = {
          type: 'ArrayAccess',
          object: expr,
          index,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      }
      // 멤버 접근: obj.property
      else if (this.match(TokenType.DOT)) {
        const propToken = this.consume(TokenType.IDENTIFIER, '프로퍼티명 필요');
        const token = this.previous();

        expr = {
          type: 'MemberAccess',
          object: expr,
          property: propToken.value,
          line: token.line,
          column: token.column,
          mode: token.mode,
        };
      } else {
        break;
      }
    }

    return expr;
  }

  /**
   * 기본 표현식 파싱 (리터럴, 식별자 등)
   */
  private parsePrimary(): AST.Expression {
    const token = this.peek();

    // 숫자
    if (token.type === TokenType.NUMBER) {
      this.advance();
      return {
        type: 'Number',
        value: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 문자열
    if (token.type === TokenType.STRING) {
      this.advance();
      return {
        type: 'String',
        value: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // true, false
    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
      this.advance();
      return {
        type: 'Number',
        value: token.type === TokenType.TRUE ? 1 : 0,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 배열 리터럴: [1, 2, 3]
    if (token.type === TokenType.LBRACKET) {
      return this.parseArrayLiteral();
    }

    // 식별자
    if (token.type === TokenType.IDENTIFIER) {
      this.advance();
      return {
        type: 'Identifier',
        name: token.value,
        line: token.line,
        column: token.column,
        mode: token.mode,
      };
    }

    // 괄호 식
    if (this.match(TokenType.LPAREN)) {
      const expr = this.parseExpression();
      this.consume(TokenType.RPAREN, ') 필요');
      return expr;
    }

    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
  }

  /**
   * 배열 리터럴 파싱
   * [1, 2, 3], [], [a+b, c*d], [1, 2,] (trailing comma 지원)
   */
  private parseArrayLiteral(): AST.ArrayLiteral {
    const startToken = this.consume(TokenType.LBRACKET, '[');
    const elements: AST.Expression[] = [];

    // 빈 배열 또는 요소들
    while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
      elements.push(this.parseExpression());

      // 쉼표가 있으면 계속, 없으면 종료
      if (!this.match(TokenType.COMMA)) {
        break;
      }

      // trailing comma: 쉼표 뒤에 ] 가 있으면 즉시 종료
      if (this.check(TokenType.RBRACKET)) {
        break;
      }
    }

    const endToken = this.consume(TokenType.RBRACKET, '] 필요');

    return {
      type: 'Array',
      elements,
      line: startToken.line,
      column: startToken.column,
      mode: startToken.mode,
    };
  }

  /**
   * 구조체 리터럴 파싱
   * Person { name: "Alice", age: 30 }
   */
  private parseStructLiteral(name: string, startLine: number, startCol: number): AST.StructLiteral {
    this.consume(TokenType.LBRACE, '{ 필요');
    this.skipNewlines();

    const fields: { [key: string]: AST.Expression } = {};

    while (this.peek().type !== TokenType.RBRACE && this.peek().type !== TokenType.EOF) {
      this.skipNewlines();
      if (this.peek().type === TokenType.RBRACE) break;

      const fieldNameToken = this.consume(TokenType.IDENTIFIER, '필드명 필요');
      this.consume(TokenType.COLON, ': 필요');
      fields[fieldNameToken.value] = this.parseExpression();

      if (this.peek().type === TokenType.COMMA) {
        this.advance();
      }
      this.skipNewlines();
    }

    this.consume(TokenType.RBRACE, '} 필요');

    return {
      type: 'StructLiteral',
      name,
      fields,
      line: startLine,
      column: startCol,
      mode: 'v',
    };
  }

  /**
   * 함수 호출 인자 파싱
   */
  private parseArguments(): AST.Expression[] {
    const args: AST.Expression[] = [];

    if (!this.check(TokenType.RPAREN)) {
      do {
        args.push(this.parseExpression());
      } while (this.match(TokenType.COMMA));
    }

    return args;
  }

  // ========== 헬퍼 메서드 ==========

  private peek(): Token {
    if (this.pos >= this.tokens.length) {
      return this.tokens[this.tokens.length - 1]; // EOF 토큰
    }
    return this.tokens[this.pos];
  }

  private peekAt(offset: number): Token {
    const idx = this.pos + offset;
    if (idx >= this.tokens.length) {
      return this.tokens[this.tokens.length - 1]; // EOF 토큰
    }
    return this.tokens[idx];
  }

  private advance(): Token {
    if (!this.isAtEnd()) {
      this.pos++;
    }
    return this.previous();
  }

  private previous(): Token {
    return this.tokens[this.pos - 1];
  }

  private isAtEnd(): boolean {
    return this.peek().type === TokenType.EOF;
  }

  private check(type: TokenType): boolean {
    if (this.isAtEnd()) return false;
    return this.peek().type === type;
  }

  private match(...types: TokenType[]): boolean {
    for (const type of types) {
      if (this.check(type)) {
        this.advance();
        return true;
      }
    }
    return false;
  }

  private consume(type: TokenType, message: string): Token {
    if (this.check(type)) return this.advance();

    const token = this.peek();
    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
  }

  private skipNewlines(): void {
    while (this.match(TokenType.NEWLINE)) {
      // 계속
    }
  }
}

/**
 * FreeLang Nexus - Phase N.5 (struct) + N.6 (match/case) 테스트
 */

import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import { NexusRunner } from '../src/nexus/runtime/nexus-runner';
import * as AST from '../src/nexus/parser/ast';

function compile(src: string) {
  const tokens = new NexusLexer(src).tokenize();
  const ast    = new NexusParser(tokens).parse();
  return new NexusCodegen().generateProgram(ast);
}

function run(src: string) {
  const tokens = new NexusLexer(src).tokenize();
  const ast    = new NexusParser(tokens).parse();
  const result = new NexusCodegen().generateProgram(ast);
  const runner = new NexusRunner();
  const r      = runner.run(result);
  return { output: r.cOutput, errors: r.errors };
}

// ─── Phase N.5 - struct ──────────────────────────────────────────────────────

describe('Phase N.5 - struct 정의 및 사용', () => {

  test('N5-1: struct 파싱 - type === StructDef', () => {
    const tokens = new NexusLexer('@mode(v)\nstruct Person { name: string, age: i64 }\n').tokenize();
    const ast    = new NexusParser(tokens).parse();
    const node   = ast.body.find((n: any) => n.type === 'StructDef') as AST.StructDef;
    expect(node).toBeDefined();
    expect(node.name).toBe('Person');
    expect(node.fields.length).toBe(2);
  });

  test('N5-2: struct 필드 타입 파싱', () => {
    const tokens = new NexusLexer('@mode(v)\nstruct Point { x: i64, y: i64 }\n').tokenize();
    const ast    = new NexusParser(tokens).parse();
    const node   = ast.body.find((n: any) => n.type === 'StructDef') as AST.StructDef;
    expect(node.fields[0].name).toBe('x');
    expect(node.fields[0].typeAnnotation).toBe('i64');
    expect(node.fields[1].name).toBe('y');
  });

  test('N5-3: struct → C typedef 생성', () => {
    const { c } = compile('@mode(v)\nstruct Person { name: string, age: i64 }\nfn main() -> i64 { return 0 }\n');
    expect(c).toContain('typedef struct {');
    expect(c).toContain('} Person;');
  });

  test('N5-4: struct 필드 C 타입 매핑', () => {
    const { c } = compile('@mode(v)\nstruct Person { name: string, age: i64 }\nfn main() -> i64 { return 0 }\n');
    expect(c).toContain('char* name;');
    expect(c).toContain('long long age;');
  });

  test('N5-5: StructLiteral → C compound literal', () => {
    const { c } = compile(`@mode(v)
struct Point { x: i64, y: i64 }
fn main() -> i64 {
  let p = Point { x: 3, y: 4 }
  return 0
}
`);
    expect(c).toContain('(Point){');
    expect(c).toContain('.x = 3');
    expect(c).toContain('.y = 4');
  });

  test('N5-6: struct 멤버 접근 - p.x', () => {
    const { c } = compile(`@mode(v)
struct Point { x: i64, y: i64 }
fn main() -> i64 {
  let p = Point { x: 10, y: 20 }
  let v = p.x
  println(v)
  return 0
}
`);
    expect(c).toContain('p.x');
  });

  test('N5-7: struct → Python class 생성', () => {
    const tokens = new NexusLexer('@mode(v)\nstruct Person { name: string, age: i64 }\n').tokenize();
    const ast    = new NexusParser(tokens).parse();
    const result = new NexusCodegen().generate(ast);
    expect(result.python).toContain('class Person:');
    expect(result.python).toContain('def __init__(self, name, age):');
    expect(result.python).toContain('self.name = name');
  });

  test('N5-8: struct 실제 실행 - 멤버 값 출력', () => {
    const { output, errors } = run(`@mode(v)
struct Point { x: i64, y: i64 }
fn main() -> i64 {
  let p = Point { x: 7, y: 3 }
  println(p.x)
  println(p.y)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('7\n3');
  });

  test('N5-9: struct 함수 파라미터', () => {
    const { c } = compile(`@mode(v)
struct Rect { w: i64, h: i64 }
fn area(r: Rect) -> i64 {
  return r.w * r.h
}
fn main() -> i64 {
  let r = Rect { w: 5, h: 4 }
  let a = area(r)
  println(a)
  return 0
}
`);
    expect(c).toContain('Rect');
    expect(c).toContain('r.w');
  });

  test('N5-10: struct 실제 실행 - area 계산', () => {
    const { output, errors } = run(`@mode(v)
struct Rect { w: i64, h: i64 }
fn area(r: Rect) -> i64 {
  return r.w * r.h
}
fn main() -> i64 {
  let r = Rect { w: 6, h: 7 }
  let a = area(r)
  println(a)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('42');
  });
});

// ─── Phase N.6 - match/case ──────────────────────────────────────────────────

describe('Phase N.6 - match/case 패턴 매칭', () => {

  test('N6-1: match 파싱 - type === MatchStatement', () => {
    const src = `@mode(v)
fn main() -> i64 {
  let x = 1
  match x {
    case 1 => { return 1 }
    case _ => { return 0 }
  }
  return 0
}
`;
    const tokens = new NexusLexer(src).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const fn     = ast.body.find((n: any) => n.type === 'VFunction') as AST.VFunction;
    const match  = fn.body.find((s: any) => s.type === 'MatchStatement') as AST.MatchStatement;
    expect(match).toBeDefined();
    expect(match.type).toBe('MatchStatement');
  });

  test('N6-2: arms 개수 파싱', () => {
    const src = `@mode(v)
fn main() -> i64 {
  let x = 2
  match x {
    case 1 => { return 1 }
    case 2 => { return 2 }
    case _ => { return 0 }
  }
  return 0
}
`;
    const tokens = new NexusLexer(src).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const fn     = ast.body.find((n: any) => n.type === 'VFunction') as AST.VFunction;
    const match  = fn.body.find((s: any) => s.type === 'MatchStatement') as AST.MatchStatement;
    expect(match.arms.length).toBe(3);
  });

  test('N6-3: 숫자 패턴 arm 파싱', () => {
    const src = `@mode(v)
fn main() -> i64 {
  let x = 1
  match x {
    case 42 => { return 1 }
    case _  => { return 0 }
  }
  return 0
}
`;
    const tokens = new NexusLexer(src).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const fn     = ast.body.find((n: any) => n.type === 'VFunction') as AST.VFunction;
    const match  = fn.body.find((s: any) => s.type === 'MatchStatement') as AST.MatchStatement;
    expect((match.arms[0].pattern as AST.NumberLiteral).value).toBe(42);
  });

  test('N6-4: wildcard arm - pattern === null', () => {
    const src = `@mode(v)
fn main() -> i64 {
  let x = 1
  match x {
    case 1 => { return 1 }
    case _ => { return 0 }
  }
  return 0
}
`;
    const tokens = new NexusLexer(src).tokenize();
    const ast    = new NexusParser(tokens).parse();
    const fn     = ast.body.find((n: any) => n.type === 'VFunction') as AST.VFunction;
    const match  = fn.body.find((s: any) => s.type === 'MatchStatement') as AST.MatchStatement;
    expect(match.arms[1].pattern).toBeNull();
  });

  test('N6-5: C 코드 생성 - switch 구문', () => {
    const { c } = compile(`@mode(v)
fn main() -> i64 {
  let x = 1
  match x {
    case 1 => { return 1 }
    case _ => { return 0 }
  }
  return 0
}
`);
    expect(c).toContain('switch (x)');
  });

  test('N6-6: C 코드 생성 - case 라벨', () => {
    const { c } = compile(`@mode(v)
fn main() -> i64 {
  let x = 2
  match x {
    case 1 => { println(x) }
    case 2 => { println(x) }
    case _ => { println(x) }
  }
  return 0
}
`);
    expect(c).toContain('case 1:');
    expect(c).toContain('case 2:');
  });

  test('N6-7: C 코드 생성 - default 라벨', () => {
    const { c } = compile(`@mode(v)
fn main() -> i64 {
  let x = 5
  match x {
    case 1 => { return 1 }
    case _ => { return 0 }
  }
  return 0
}
`);
    expect(c).toContain('default:');
  });

  test('N6-8: C 코드 생성 - break 자동 삽입', () => {
    const { c } = compile(`@mode(v)
fn main() -> i64 {
  let x = 1
  match x {
    case 1 => { println(x) }
    case _ => { println(x) }
  }
  return 0
}
`);
    expect(c).toContain('break;');
  });

  test('N6-9: 실제 실행 - case 1 매칭', () => {
    const { output, errors } = run(`@mode(v)
fn main() -> i64 {
  let x = 1
  match x {
    case 1 => { println(x) }
    case 2 => { println(x) }
    case _ => { println(x) }
  }
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('1');
  });

  test('N6-10: 실제 실행 - wildcard 매칭', () => {
    const { output, errors } = run(`@mode(v)
fn main() -> i64 {
  let x = 99
  match x {
    case 1  => { println(x) }
    case 2  => { println(x) }
    case _  => { println(x) }
  }
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('99');
  });

  test('N6-11: 실제 실행 - 문자열 케이스', () => {
    const { output, errors } = run(`@mode(v)
fn grade(n: i64) -> i64 {
  match n {
    case 1 => { println("one") }
    case 2 => { println("two") }
    case 3 => { println("three") }
    case _ => { println("other") }
  }
  return 0
}
fn main() -> i64 {
  grade(2)
  grade(3)
  grade(9)
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('two\nthree\nother');
  });

  test('N6-12: 실제 실행 - match + for 루프 혼합', () => {
    const { output, errors } = run(`@mode(v)
fn main() -> i64 {
  let i = 1
  while i <= 5 {
    match i {
      case 1 => { println(i) }
      case 3 => { println(i) }
      case 5 => { println(i) }
      case _ => { println(0) }
    }
    i = i + 1
  }
  return 0
}
`);
    expect(errors).toHaveLength(0);
    expect(output.trim()).toBe('1\n0\n3\n0\n5');
  });
});
